package org.gaokun.hosprobe;
import android.app.*;import android.os.*;import android.content.*;import android.hardware.*;import android.hardware.camera2.*;import android.media.*;import android.bluetooth.*;import android.bluetooth.le.*;import android.view.*;import android.widget.*;import android.graphics.ImageFormat;import android.util.Size;import android.security.keystore.*;import java.io.*;import java.net.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import javax.crypto.*;
public class Main extends Activity {
 Handler h=new Handler(Looper.getMainLooper()); TextView status; StringBuilder report=new StringBuilder(); HandlerThread cameraThread;
 synchronized void log(String s){report.append(s).append('\n');android.util.Log.i("HosProbe",s);try(FileOutputStream f=openFileOutput("results.txt",0)){f.write(report.toString().getBytes());}catch(Exception e){} h.post(()->status.setText(report.toString()));}
 interface Test {void run() throws Exception;}
 void test(String n,Test t){log("BEGIN "+n);try{t.run();}catch(Throwable e){log("FAIL "+n+" "+e);} }
 public void onCreate(Bundle b){super.onCreate(b);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);status=new TextView(this);status.setTextSize(16);ScrollView sc=new ScrollView(this);sc.addView(status);setContentView(sc); if(getIntent().hasExtra("orientation")){setRequestedOrientation(getIntent().getIntExtra("orientation",0));status.setText("Orientation/input diagnostic. Drag to test touch; no capture.");sc.setOnTouchListener((v,e)->{android.util.Log.i("HosTouch", "action="+e.getActionMasked()+" pointers="+e.getPointerCount()+" x="+e.getX()+" y="+e.getY());return true;});return;}new Thread(()->{if(getIntent().getBooleanExtra("thermal_only",false)){test("thermal",()->ThermalProbe.run(this));log("DONE THERMAL");}else if(getIntent().getBooleanExtra("strict_sensors",false)){test("strict-sensors",()->StrictSensors.run(this,getIntent().getIntExtra("sensor_rounds",1)));log("DONE STRICT SENSORS");}else if(getIntent().getBooleanExtra("codec_only",false)){test("AVC-roundtrip",()->codec());log("DONE CODEC");}else if(getIntent().getBooleanExtra("media",false))runMedia();else run();}).start();}
 void run(){
 test("storage",()->{byte[] b=new byte[1024*1024];new Random(44).nextBytes(b);File f=new File(getFilesDir(),"io-test");long t=System.nanoTime();try(FileOutputStream o=new FileOutputStream(f)){for(int i=0;i<16;i++)o.write(b);o.getFD().sync();}try(FileInputStream in=new FileInputStream(f)){byte[] r=new byte[b.length];for(int i=0;i<16;i++){int n=0;while(n<r.length){int k=in.read(r,n,r.length-n);if(k<0)throw new IOException("short read");n+=k;}if(!Arrays.equals(b,r))throw new IOException("mismatch");}}finally{f.delete();}log("PASS storage 16MiB write+fsync+read bytes matched ms="+(System.nanoTime()-t)/1000000);});
 test("https",()->{HttpURLConnection c=(HttpURLConnection)new URL("https://www.baidu.com/").openConnection();c.setConnectTimeout(10000);c.setReadTimeout(10000);try{int code=c.getResponseCode();int n=c.getInputStream().read(new byte[4096]);log((code==200&&n>0?"PASS":"FAIL")+" https code="+code+" bytes="+n);}finally{c.disconnect();}});
 test("sensors",()->StrictSensors.run(this,1));
 test("audio",()->{int rate=48000;int min=AudioRecord.getMinBufferSize(rate,AudioFormat.CHANNEL_IN_MONO,AudioFormat.ENCODING_PCM_16BIT);AudioRecord rec=new AudioRecord(MediaRecorder.AudioSource.MIC,rate,AudioFormat.CHANNEL_IN_MONO,AudioFormat.ENCODING_PCM_16BIT,Math.max(min,rate));AudioTrack tr=null;try{log("audio record state="+rec.getState());rec.startRecording();short[] tone=new short[rate];for(int i=0;i<tone.length;i++)tone[i]=(short)(1800*Math.sin(2*Math.PI*660*i/rate));tr=new AudioTrack(AudioManager.STREAM_MUSIC,rate,AudioFormat.CHANNEL_OUT_MONO,AudioFormat.ENCODING_PCM_16BIT,tone.length*2,AudioTrack.MODE_STATIC);tr.write(tone,0,tone.length);tr.play();short[] data=new short[2400];long total=0,squares=0;int peak=0;for(int i=0;i<60;i++){int n=rec.read(data,0,data.length,AudioRecord.READ_BLOCKING);if(n<=0)throw new IOException("record read="+n);for(int j=0;j<n;j++){int v=data[j];squares+=(long)v*v;peak=Math.max(peak,Math.abs(v));}total+=n;}log((total>0&&peak>0?"PASS":"FAIL")+" microphone samples="+total+" rms="+Math.sqrt((double)squares/total)+" peak="+peak);log((tr.getPlaybackHeadPosition()>0?"PASS":"FAIL")+" playback frames="+tr.getPlaybackHeadPosition()+" (audibility unverified)");}finally{if(rec.getRecordingState()==3)rec.stop();rec.release();if(tr!=null)tr.release();}});
 cameraThread=new HandlerThread("camera-probe");cameraThread.start();test("cameras",()->{CameraManager cm=(CameraManager)getSystemService(CAMERA_SERVICE);for(String id:cm.getCameraIdList())test("camera-"+id,()->camera(cm,id));});cameraThread.quitSafely();
 test("keystore",()->{String alias="hos-probe-temp";java.security.KeyStore ks=java.security.KeyStore.getInstance("AndroidKeyStore");ks.load(null);try{KeyGenerator kg=KeyGenerator.getInstance("AES","AndroidKeyStore");kg.init(new KeyGenParameterSpec.Builder(alias,KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());javax.crypto.SecretKey key=kg.generateKey();Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,key);byte[] encrypted=c.doFinal("probe".getBytes());log("PASS keystore AES/GCM encrypted bytes="+encrypted.length);}finally{if(ks.containsAlias(alias))ks.deleteEntry(alias);}});
 test("bluetooth",()->{BluetoothAdapter a=getSystemService(BluetoothManager.class).getAdapter();log("bluetooth enabled="+a.isEnabled()+" bondedCount="+a.getBondedDevices().size());if(!a.isEnabled()){log("SKIP bluetooth scan adapter off");return;}AtomicInteger found=new AtomicInteger();ScanCallback cb=new ScanCallback(){public void onScanResult(int t,ScanResult r){found.incrementAndGet();}public void onScanFailed(int e){log("FAIL BLE scan code="+e);}};BluetoothLeScanner scanner=a.getBluetoothLeScanner();try{scanner.startScan(cb);Thread.sleep(8000);}finally{scanner.stopScan(cb);}log("BLE scan advertisements="+found+" (pairing untested)");});
 test("codecs",()->{int en=0,de=0;for(MediaCodecInfo c:new MediaCodecList(MediaCodecList.REGULAR_CODECS).getCodecInfos()){if(c.isEncoder())en++;else de++;}log("codec inventory encoders="+en+" decoders="+de+" (stream test separate)");});log("DONE");
 }
 void camera(CameraManager cm,String id)throws Exception{
 Handler ch=new Handler(cameraThread.getLooper());CameraCharacteristics cc=cm.getCameraCharacteristics(id);Size[] sizes=cc.get(CameraCharacteristics.SCALER_STREAM_CONFIGURATION_MAP).getOutputSizes(ImageFormat.YUV_420_888);Size pick=Arrays.stream(sizes).min(Comparator.comparingLong(s->(long)s.getWidth()*s.getHeight())).get();log("camera "+id+" facing="+cc.get(CameraCharacteristics.LENS_FACING)+" size="+pick);ImageReader ir=ImageReader.newInstance(pick.getWidth(),pick.getHeight(),ImageFormat.YUV_420_888,3);AtomicInteger frames=new AtomicInteger();AtomicLong sum=new AtomicLong(),pixels=new AtomicLong();ir.setOnImageAvailableListener(r->{try(Image im=r.acquireLatestImage()){if(im!=null){frames.incrementAndGet();java.nio.ByteBuffer b=im.getPlanes()[0].getBuffer();for(int i=0;i<b.remaining();i+=64){sum.addAndGet(b.get(i)&255);pixels.incrementAndGet();}}}},ch);CountDownLatch opened=new CountDownLatch(1),ready=new CountDownLatch(1);AtomicReference<CameraDevice> dev=new AtomicReference<>();AtomicReference<CameraCaptureSession> session=new AtomicReference<>();AtomicReference<String> error=new AtomicReference<>();try{cm.openCamera(id,new CameraDevice.StateCallback(){public void onOpened(CameraDevice d){dev.set(d);opened.countDown();}public void onDisconnected(CameraDevice d){error.set("disconnected");d.close();opened.countDown();}public void onError(CameraDevice d,int e){error.set("open="+e);d.close();opened.countDown();}},ch);if(!opened.await(8,TimeUnit.SECONDS)||dev.get()==null)throw new IOException("camera open "+error.get());dev.get().createCaptureSession(Arrays.asList(ir.getSurface()),new CameraCaptureSession.StateCallback(){public void onConfigured(CameraCaptureSession s){session.set(s);ready.countDown();}public void onConfigureFailed(CameraCaptureSession s){error.set("configure");ready.countDown();}},ch);if(!ready.await(8,TimeUnit.SECONDS)||session.get()==null)throw new IOException("camera session "+error.get());CaptureRequest.Builder req=dev.get().createCaptureRequest(CameraDevice.TEMPLATE_PREVIEW);req.addTarget(ir.getSurface());session.get().setRepeatingRequest(req.build(),null,ch);Thread.sleep(3000);log((frames.get()>5?"PASS":"FAIL")+" camera "+id+" YUV frames="+frames+" meanLuma="+(pixels.get()>0?(double)sum.get()/pixels.get():0)+" no images saved");}finally{if(session.get()!=null)session.get().close();if(dev.get()!=null)dev.get().close();Thread.sleep(300);ir.close();}}
 void runMedia(){cameraThread=new HandlerThread("jpeg-probe");cameraThread.start();test("JPEG",()->{CameraManager cm=getSystemService(CameraManager.class);for(String id:cm.getCameraIdList())test("JPEG-"+id,()->jpeg(cm,id));});cameraThread.quitSafely();test("AVC-roundtrip",()->codec());log("DONE MEDIA");}
 void jpeg(CameraManager cm,String id)throws Exception{Handler ch=new Handler(cameraThread.getLooper());Size[] sizes=cm.getCameraCharacteristics(id).get(CameraCharacteristics.SCALER_STREAM_CONFIGURATION_MAP).getOutputSizes(ImageFormat.JPEG);Size size=Arrays.stream(sizes).min(Comparator.comparingLong(s->(long)s.getWidth()*s.getHeight())).get();ImageReader ir=ImageReader.newInstance(size.getWidth(),size.getHeight(),ImageFormat.JPEG,2);CountDownLatch open=new CountDownLatch(1),configured=new CountDownLatch(1),image=new CountDownLatch(1);AtomicReference<CameraDevice>d=new AtomicReference<>();AtomicReference<CameraCaptureSession>s=new AtomicReference<>();ir.setOnImageAvailableListener(r->{try(Image im=r.acquireNextImage()){if(im!=null){java.nio.ByteBuffer b=im.getPlanes()[0].getBuffer();boolean ok=b.remaining()>100&& (b.get(0)&255)==255&&(b.get(1)&255)==216;log((ok?"PASS":"FAIL")+" JPEG camera="+id+" size="+size+" bytes="+b.remaining()+" no file saved");image.countDown();}}},ch);try{cm.openCamera(id,new CameraDevice.StateCallback(){public void onOpened(CameraDevice c){d.set(c);open.countDown();}public void onDisconnected(CameraDevice c){c.close();open.countDown();}public void onError(CameraDevice c,int e){c.close();open.countDown();}},ch);if(!open.await(8,TimeUnit.SECONDS)||d.get()==null)throw new IOException("open timeout/error");d.get().createCaptureSession(Arrays.asList(ir.getSurface()),new CameraCaptureSession.StateCallback(){public void onConfigured(CameraCaptureSession c){s.set(c);configured.countDown();}public void onConfigureFailed(CameraCaptureSession c){configured.countDown();}},ch);if(!configured.await(8,TimeUnit.SECONDS)||s.get()==null)throw new IOException("configure timeout/error");CaptureRequest.Builder r=d.get().createCaptureRequest(CameraDevice.TEMPLATE_STILL_CAPTURE);r.addTarget(ir.getSurface());s.get().capture(r.build(),null,ch);if(!image.await(10,TimeUnit.SECONDS))throw new IOException("JPEG timeout");}finally{if(s.get()!=null)s.get().close();if(d.get()!=null)d.get().close();Thread.sleep(300);ir.close();}}
 void codec()throws Exception{int frameCount=getIntent().getIntExtra("frames",120);if(frameCount<1||frameCount>240)throw new IllegalArgumentException("frames");MediaFormat f=MediaFormat.createVideoFormat("video/avc",320,240);f.setInteger(MediaFormat.KEY_COLOR_FORMAT,MediaCodecInfo.CodecCapabilities.COLOR_FormatYUV420Flexible);f.setInteger(MediaFormat.KEY_BIT_RATE,500000);f.setInteger(MediaFormat.KEY_FRAME_RATE,30);f.setInteger(MediaFormat.KEY_I_FRAME_INTERVAL,1);MediaCodec enc=MediaCodec.createEncoderByType("video/avc");List<byte[]> packets=new ArrayList<>();List<Integer> flags=new ArrayList<>();MediaFormat encoded=null;MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();int sent=0;boolean eos=false;long deadline=System.currentTimeMillis()+45000;try{log("AVC encoder="+enc.getName());enc.configure(f,null,null,MediaCodec.CONFIGURE_FLAG_ENCODE);enc.start();while(!eos&&System.currentTimeMillis()<deadline){if(sent<=frameCount){int idx=enc.dequeueInputBuffer(10000);if(idx>=0){java.nio.ByteBuffer b=enc.getInputBuffer(idx);int len=sent==frameCount?0:320*240*3/2;for(int j=0;j<len;j++)b.put((byte)(j<320*240?32+sent*8:128));enc.queueInputBuffer(idx,0,len,sent*33333L,sent==frameCount?MediaCodec.BUFFER_FLAG_END_OF_STREAM:0);sent++;}}int o=enc.dequeueOutputBuffer(info,10000);if(o==MediaCodec.INFO_OUTPUT_FORMAT_CHANGED)encoded=enc.getOutputFormat();if(o>=0){if(info.size>0&&(info.flags&MediaCodec.BUFFER_FLAG_CODEC_CONFIG)==0){byte[] b=new byte[info.size];java.nio.ByteBuffer buf=enc.getOutputBuffer(o);buf.position(info.offset);buf.get(b);packets.add(b);flags.add(info.flags);}eos=(info.flags&MediaCodec.BUFFER_FLAG_END_OF_STREAM)!=0;enc.releaseOutputBuffer(o,false);}}}finally{enc.release();}if(!eos||packets.size()!=frameCount||encoded==null)throw new IOException("encode packets="+packets.size()+" eos="+eos);String decoderName=getIntent().getStringExtra("decoder");MediaCodec dec=decoderName==null?MediaCodec.createDecoderByType("video/avc"):MediaCodec.createByCodecName(decoderName);int fed=0,frames=0;boolean ended=false;deadline=System.currentTimeMillis()+45000;try{log("AVC decoder="+dec.getName());dec.configure(encoded,null,null,0);dec.start();while(!ended&&System.currentTimeMillis()<deadline){if(fed<=packets.size()){int i=dec.dequeueInputBuffer(10000);if(i>=0){boolean end=fed==packets.size();byte[] b=end?new byte[0]:packets.get(fed);dec.getInputBuffer(i).put(b);dec.queueInputBuffer(i,0,b.length,fed*33333L,end?MediaCodec.BUFFER_FLAG_END_OF_STREAM:0);fed++;}}int o=dec.dequeueOutputBuffer(info,10000);if(o>=0){if(info.size>0)frames++;ended=(info.flags&MediaCodec.BUFFER_FLAG_END_OF_STREAM)!=0;dec.releaseOutputBuffer(o,false);}}log((ended&&frames==frameCount?"PASS":"FAIL")+" AVC roundtrip encoded="+packets.size()+" decoded="+frames+" EOS="+ended);}finally{dec.release();}}

}
